import{_ as e,o,c,a as d}from"./app-be7ae715.js";const l={},t=d("<ol><li><code>beforeEach</code> 在路由发生变化才触发，导航到本身不触发，参数变化时触发。</li><li><code>beforeRouteUpdate</code> 路由匹配不变，参数更新，组件重用触发</li><li><code>beforeEnter</code> 路由变化触发</li><li><code>beforeRouteEnter</code> 第一次进入匹配项触发</li><li><code>beforeResolve</code> 路由变化触发</li><li><code>afterEach</code> 必定触发</li><li><code>-----------------------------------------------------</code></li><li><code>created</code></li><li><code>beforeRouteEnter next</code></li><li><code>mounted / update</code></li><li><code>beforeRouteLeave</code> 路由离开当前匹配项</li><li><code>--------------------------------------------------</code></li></ol><p>总结：</p><ol><li>路由变化(url)一定触发 <code>beforeEach</code> 和 <code>beforeResolve</code></li><li>匹配到的路由项变化，触发 <code>beforeEnter</code> 和 <code>beforeRouteEnter</code></li><li>路由变化触发组件更新 <code>update</code></li><li>多个路由项匹配同一个组件时，组件将被复用，只触发<code>update</code>更新 ex: /test2/:A -&gt; /test/:A 两者都使用Test组件， 导航更新只触发<code>update</code></li><li>组件内路由守卫只支持在router配置项中直接注册的组件，子组件的钩子不会在路由变化时触发。</li><li>路由变化会导致直接组件更新</li></ol>",3),i=[t];function r(a,u){return o(),c("div",null,i)}const f=e(l,[["render",r],["__file","vue router.html.vue"]]);export{f as default};
